package main

import (
    "fmt"
    "io"
    "net/http"
)

func main() {
    request, err := http.NewRequest("GET", "https://api.widgetic.com/v1/widgets?page=1&size=1", nil)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }
    request.Header.Set("Authorization", "Bearer YOUR_API_KEY")

    response, err := http.DefaultClient.Do(request)
    if err != nil {
        fmt.Printf("Error: %v\n", err)
        return
    }
    defer response.Body.Close()

    body, _ := io.ReadAll(response.Body)
    fmt.Println(response.StatusCode, string(body))
}

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

public class Example {
    public static void main(String[] args) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://api.widgetic.com/v1/widgets?page=1&size=1"))
            .header("Authorization", "Bearer YOUR_API_KEY")
            .method("GET", HttpRequest.BodyPublishers.noBody())
            .build();

        HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
        System.out.println(response.statusCode() + " " + response.body());
    }
}

