import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.util.UUID;

public class Example {
    public static void main(String[] args) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create("https://api.widgetic.com/v1/widgets"))
            .header("Authorization", "Bearer YOUR_API_KEY")
            .header("Content-Type", "application/json")
            .header("Idempotency-Key", UUID.randomUUID().toString())
            .method("POST", HttpRequest.BodyPublishers.ofString("{\n  \"name\": \"New Chart Widget\",\n  \"type\": \"chart\",\n  \"content\": {\n    \"chartType\": \"bar\",\n    \"dataSource\": \"api\"\n  },\n  \"isPublic\": false,\n  \"isDraft\": false,\n  \"canvasId\": \"abc12345-def6-7890-ab12-cd3456ef7890\",\n  \"projectId\": \"7c1e2f30-4a5b-4c6d-8e9f-0a1b2c3d4e5f\",\n  \"organizationId\": \"5e2d3f4a-1b6c-4a1f-8b9c-3c2d4e5f6a7b\",\n  \"workspaceType\": \"personal\",\n  \"managedUserId\": \"b7c8d9e0-1f2a-4b3c-8d4e-5f6a7b8c9d0e\",\n  \"managedUserExternalId\": \"user-8841\"\n}"))
            .build();

        HttpResponse<String> response = HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString());
        System.out.println(response.statusCode() + " " + response.body());
    }
}

